# ===== Funções de acesso =====
def get_sig(n, lang="pt"):
    d = SIG.get(n)
    if not d: return ("Número único", "Número único, como você.", "", "")
    return d

def get_cam(n, lang="pt"):
    d = CAM.get(n)
    if not d: return ("", "")
    return d

def get_des(n, lang="pt"):
    return DES.get(n, "")

def get_vib(n, lang="pt"):
    return VIB.get(n, "")
